const ymd=(d=now())=>`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;
const dateOf=s=>{const x=String(s).split('-');return new Date(Number(x[0]),Number(x[1])-1,Number(x[2]),12)};
const addDays=(s,n)=>{let d=dateOf(s);d.setDate(d.getDate()+n);return ymd(d)};
const startWeek=(date=ymd())=>{let d=dateOf(date),dw=(d.getDay()+6)%7;d.setDate(d.getDate()-dw);return ymd(d)};
