const num=(v,d=0)=>Number(v||0).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const nval=v=>Number.isFinite(Number(v))?Number(v):0;
const clamp=(v,min,max)=>Math.max(min,Math.min(max,v));
const minutes=n=>{let v=Math.max(0,Math.floor(n||0));return `${Math.floor(v/60)}h ${pad(v%60)}m`};
