function macroBar(kind,label,value,target,unit){return `<div class="macro ${kind}"><div class="macro-top"><span>${esc(label)}</span><strong>${num(value)} / ${num(target)} ${unit}</strong></div><div class="progress-track"><div class="progress-fill" style="width:${target?clamp(value/target*100,0,100):0}%"></div></div></div>`}
function topRecords(n=4){const ranked=state.exercises.map(e=>({exercise:e,pr:exercisePR(e.id)})).filter(e=>e.pr.weight>0).sort((a,b)=>b.pr.weight-a.pr.weight).slice(0,n);return ranked.length?ranked.map(x=>`<div class="list-row"><div class="list-icon">${icon('trophy')}</div><div class="list-main"><strong>${esc(x.exercise.name)}</strong><small>${esc(x.exercise.muscle)} · Best weight</small></div><div class="list-right">${num(x.pr.weight,1)} ${esc(state.settings.unit)}</div></div>`).join(''):empty('trophy','Records unlock with training','Your personal bests appear after you complete weighted sets.')}
