function nutritionPage(){const d=ui.nutritionDate,items=nutritionDay(d),tot=macroTotal(items),s=state.settings,byMeal=['Breakfast','Lunch','Dinner','Snacks'];let week=Array.from({length:7},(_,i)=>{let day=addDays(startWeek(d),i);return {day,calories:macroTotal(nutritionDay(day)).calories}});
return `${sectionIntro('Nutrition tracker','Track calories and macros with your own food entries.',btn('Log food','log-food','plus','button-primary'))}
<div class="filter-row"><div class="field" style="max-width:210px"><label>Food diary date</label><input type="date" class="form-control" data-ui-date="nutritionDate" value="${d}"/></div>${btn('Today','nutrition-today','calendar-days','button-tiny')}${btn('Save a food','add-food-preset','plus','button-tiny')}</div>
<div class="grid g4">${statCard('Calories logged',`${num(tot.calories)}`,'kcal consumed','flame')}${statCard('Protein',`${num(tot.protein)} <span style="font-size:13px">g</span>`,`Target ${num(s.protein)} g`,'dumbbell')}${statCard('Carbohydrates',`${num(tot.carbs)} <span style="font-size:13px">g</span>`,`Target ${num(s.carbs)} g`,'zap')}${statCard('Fat',`${num(tot.fats)} <span style="font-size:13px">g</span>`,`Target ${num(s.fats)} g`,'target')}</div><div class="sp-18"></div>
<div class="split-2"><div class="panel">${panelHead('Daily intake',fmtDate(d,{weekday:'long',month:'long',day:'numeric',year:'numeric'}),'')}
<div class="food-progress">${donut(tot.calories,nval(s.calories),'kcal logged')}<div>${macroBar('protein','Protein',tot.protein,nval(s.protein),'g')}${macroBar('carbs','Carbs',tot.carbs,nval(s.carbs),'g')}${macroBar('fats','Fat',tot.fats,nval(s.fats),'g')}</div></div><div class="sp-18"></div><p class="caption">Nutritional values are entered by you; OS Fit does not verify food-label accuracy. Targets are your personal settings, not medical recommendations.</p></div>
<div class="panel">${panelHead('Calories this week','Logged calorie intake by day')}${barChart(week.map(x=>x.calories),week.map(x=>DAYS[dateOf(x.day).getDay()]))}<div class="legend"><span class="legend-item"><i class="legend-dot" style="background:var(--accent)"></i> Calories logged</span><span class="legend-item">Daily goal: ${num(s.calories)} kcal</span></div></div></div>
<div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Food diary',`${items.length} entries on ${fmtDate(d)}`,btn('Add food','log-food','plus','button-tiny'))}${items.length?byMeal.map(meal=>{let logs=items.filter(x=>x.meal===meal);return !logs.length?'':`<div class="meal-group"><h4>${meal}</h4>${logs.map(x=>`<div class="meal-row"><div class="meal-icon">${icon('utensils')}</div><div class="list-main"><strong>${esc(x.name)}</strong><small>${esc(x.serving||'1 serving')} · P ${num(x.protein)}g · C ${num(x.carbs)}g · F ${num(x.fats)}g</small></div><div class="meal-cal">${num(x.calories)}<small>kcal</small></div><button class="icon-button" data-act="delete-meal" data-id="${esc(x.id)}" aria-label="Delete food entry">${icon('trash',14)}</button></div>`).join('')}</div>`}).join(''):empty('utensils','Food diary is empty','Add your first meal and keep your calorie and macro targets in sight.','log-food','Log food')}</div>
<div class="panel">${panelHead('Saved foods','Your personal reusable food library',btn('Save new food','add-food-preset','plus','button-tiny'))}${state.foods.length?state.foods.map(f=>`<div class="list-row"><div class="list-icon">${icon('coffee')}</div><div class="list-main"><strong>${esc(f.name)}</strong><small>${esc(f.serving)} · ${num(f.protein)}P / ${num(f.carbs)}C / ${num(f.fats)}F</small></div><div class="list-right">${num(f.calories)} kcal</div><button class="button button-tiny" data-act="log-saved-food" data-id="${esc(f.id)}">Log</button><button class="icon-button" data-act="delete-saved-food" data-id="${esc(f.id)}" aria-label="Delete saved food">${icon('x',14)}</button></div>`).join(''):empty('coffee','No saved foods','Save foods you eat often for faster daily logging.')}</div></div>${recipesPanel()}`}
function progressPage(){const logs=[...state.bodyLogs].sort((a,b)=>a.date.localeCompare(b.date)),last=logs.at(-1),first=logs[0],field=ui.weightField,fieldLabels={weight:'Body weight',bodyFat:'Body fat',chest:'Chest',waist:'Waist',hips:'Hips',arm:'Upper arm',thigh:'Thigh'};let valid=logs.filter(x=>x[field]!==''&&x[field]!=null&&Number.isFinite(Number(x[field]))),diff=valid.length>=2?nval(valid.at(-1)[field])-nval(valid[0][field]):null;let weightLogs=logs.filter(x=>x.weight!=null),weightDiff=weightLogs.length>=2?nval(weightLogs.at(-1).weight)-nval(weightLogs[0].weight):null;const unit=field==='weight'?state.settings.unit:field==='bodyFat'?'%':'cm';return `${sectionIntro('Body progress','Track body weight, measurements, strength and photos over time.',btn('Add measurement','body-log','plus','button-primary')+btn('Add progress photo','photo-log','camera'))}
<div class="grid g4">${statCard('Current weight',last?.weight!=null?`${num(last.weight,1)} <span style="font-size:13px">${esc(state.settings.unit)}</span>`:'—','Latest weigh-in','scale')}${statCard('Weight change',weightDiff!=null?`${weightDiff>0?'+':''}${num(weightDiff,1)} <span style="font-size:13px">${esc(state.settings.unit)}</span>`:'—','From first to latest entry','chart-line')}${statCard('Body measurements',`${logs.length}`,'Logged check-ins','activity')}${statCard('Photos',`${state.photos.length}`,'Stored only in this browser','camera')}</div><div class="sp-18"></div>
<div class="split-2"><div class="panel">${panelHead('Body metrics trend','A visual history of your check-ins',`<select class="select-control" style="width:auto;max-width:180px;font-size:11px" data-ui-field="weightField">${Object.entries(fieldLabels).map(([k,v])=>`<option value="${k}" ${field===k?'selected':''}>${v}</option>`).join('')}</select>`)}${valid.length>1?lineChart(valid.map(x=>nval(x[field])),{labels:valid.map(x=>fmtDate(x.date)),suffix:' '+unit}):empty('chart-line','Your trend starts here','Log two measurements to see how things change.')}${diff!=null?`<p class="caption">${esc(fieldLabels[field])}: ${diff>0?'+':''}${num(diff,1)} ${unit} since first record</p>`:''}</div><div class="panel">${panelHead('Latest measurements','Most recent recorded values',btn('New check-in','body-log','plus','button-tiny'))}${last?Object.entries(fieldLabels).map(([k,v])=>`<div class="list-row"><div class="list-main"><strong>${v}</strong></div><div class="list-right">${last[k]==null||last[k]===''?'—':`${num(last[k],1)} ${k==='weight'?state.settings.unit:k==='bodyFat'?'%':'cm'}`}</div></div>`).join(''):empty('scale','No measurements yet','Log weight, waist and other measurements as often as you prefer.','body-log','Add measurement')}</div></div>
<div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Measurement history','Your previous body check-ins')}${logs.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Weight</th><th>Waist</th><th>Chest</th><th>Body fat</th><th></th></tr></thead><tbody>${[...logs].reverse().map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${x.weight==null?'—':num(x.weight,1)}</td><td>${x.waist==null?'—':num(x.waist,1)}</td><td>${x.chest==null?'—':num(x.chest,1)}</td><td>${x.bodyFat==null?'—':num(x.bodyFat,1)+'%'}</td><td><button class="button button-tiny" data-act="edit-body" data-id="${esc(x.id)}">${icon('edit',13)}</button><button class="button button-tiny button-danger" data-act="delete-body" data-id="${esc(x.id)}">${icon('trash',13)}</button></td></tr>`).join('')}</tbody></table></div>`:empty('activity','No check-ins yet','A few measurements create your progress trend.')}</div>
<div class="panel">${panelHead('Strength records','Based on your completed sets',`<span class="panel-badge">ESTIMATED 1RM</span>`)}${state.exercises.map(e=>({e,pr:exercisePR(e.id)})).filter(x=>x.pr.weight>0).sort((a,b)=>b.pr.e1rm-a.pr.e1rm).slice(0,6).map(x=>`<div class="list-row"><div class="list-icon">${icon('trophy')}</div><div class="list-main"><strong>${esc(x.e.name)}</strong><small>Best ${num(x.pr.weight,1)} ${state.settings.unit} · est. 1RM (Epley)</small></div><div class="list-right">${num(x.pr.e1rm,1)} ${state.settings.unit}</div></div>`).join('')||empty('trophy','No strength PRs','Complete weighted sets to track your personal records.')}</div></div>
<div class="sp-18"></div><div class="panel">${panelHead('Progress photo gallery','Private local photos · included in your exported JSON backup',btn('Add photo','photo-log','camera','button-tiny'))}${state.photos.length?`<div class="photo-grid">${[...state.photos].sort((a,b)=>b.date.localeCompare(a.date)).map(p=>`<div class="photo-tile"><img src="${esc(p.data)}" alt="Progress photo on ${esc(p.date)}" loading="lazy"><div class="photo-info"><strong>${fmtDate(p.date)}</strong><div>${esc(p.note||'Progress photo')}</div></div><button data-act="delete-photo" data-id="${esc(p.id)}" aria-label="Delete photo">${icon('x',15)}</button></div>`).join('')}</div>`:empty('camera','Capture the process','Add a progress photo. Photos remain on this device unless exported in a backup.','photo-log','Add photo')}<div class="sp-8"></div><div class="data-warning"><strong>Privacy note:</strong> Photos are saved in your browser storage and included in any JSON backup. They are not uploaded to the cloud. Use a private device and keep backups secure.</div></div>${bodyComparisonPanel()}`}
function calendarPage(){let [yy,mm]=ui.calendarMonth.split('-').map(Number),start=new Date(yy,mm-1,1,12),startWd=(start.getDay()+6)%7,daysInMonth=new Date(yy,mm,0).getDate(),cells=Math.ceil((daysInMonth+startWd)/7)*7,p=plan();let scheduled={};for(let i=1;i<=daysInMonth;i++){let d=`${yy}-${pad(mm)}-${pad(i)}`,wd=dateOf(d).getDay();scheduled[d]=(p?.days||[]).filter(x=>{const move=state.reschedules.find(q=>q.planId===p.id&&q.dayId===x.id&&q.originalWeek===startWeek(d));return move?move.date===d:x.weekday===wd})}let selected=ui.calendarSelected;if(!sameMonth(selected,ui.calendarMonth+'-01'))selected=ui.calendarMonth+'-01';let sess=state.sessions.filter(s=>s.date===selected),nut=nutritionDay(selected),body=state.bodyLogs.filter(x=>x.date===selected);return `${sectionIntro('Training calendar','See planned sessions, completed workouts and check-ins in one view.',btn('Start workout','start-workout','plus','button-primary'))}<div class="split-2"><div class="panel"><div class="calendar-head"><div><span class="eyebrow">MONTHLY OVERVIEW</span><h3>${start.toLocaleDateString('en-US',{month:'long',year:'numeric'})}</h3></div><div style="display:flex;gap:7px"><button class="icon-button" data-act="calendar-prev" aria-label="Previous month">${icon('chevron-left')}</button><button class="icon-button" data-act="calendar-today" aria-label="Current month">${icon('calendar-days')}</button><button class="icon-button" data-act="calendar-next" aria-label="Next month">${icon('chevron-right')}</button></div></div>
<div class="calendar-grid">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="cal-weekday">${d}</div>`).join('')}${Array.from({length:cells},(_,i)=>{let dayNum=i-startWd+1,inMonth=dayNum>=1&&dayNum<=daysInMonth;let d=new Date(yy,mm-1,dayNum,12),date=ymd(d),work=state.sessions.filter(s=>s.date===date),sched=inMonth?(scheduled[date]||[]):[],weight=state.bodyLogs.some(x=>x.date===date);return `<button class="cal-day ${inMonth?'':'other'} ${date===ymd()?'today':''} ${date===selected?'selected':''}" data-act="calendar-pick" data-date="${date}"><span class="cal-number">${d.getDate()}</span>${work.length?`<span class="cal-marker logged">${work.length} done</span>`:sched.length?`<span class="cal-marker">${esc(sched[0].title)}</span>`:''}${weight?`<span class="cal-marker weight">Check-in</span>`:''}</button>`}).join('')}</div><div class="sp-18"></div><div class="legend"><span class="legend-item"><i class="legend-dot" style="background:var(--accent)"></i> Planned</span><span class="legend-item"><i class="legend-dot" style="background:var(--blue)"></i> Completed</span><span class="legend-item"><i class="legend-dot" style="background:var(--warning)"></i> Body check-in</span></div></div>
<div class="panel">${panelHead(fmtDate(selected,{weekday:'long',month:'long',day:'numeric'}),'Daily overview')}${sess.length?sess.map(x=>`<div class="list-row"><div class="list-icon">${icon('check-circle')}</div><div class="list-main"><strong>${esc(x.title)}</strong><small>${totalSets(x)} completed sets · ${minutes(x.durationMinutes)}</small></div><button class="button button-tiny" data-act="view-session" data-id="${esc(x.id)}">View</button></div>`).join(''):`<div class="empty-state" style="padding:10px"><p>No completed workouts on this day.</p></div>`}<hr class="tiny-divider"><h4 class="section-label">Scheduled sessions</h4>${(p?.days.filter(x=>x.weekday===dateOf(selected).getDay())||[]).map(d=>`<div class="list-row"><div class="list-main"><strong>${esc(d.title)}</strong><small>${d.items.length} exercises · ${esc(p.name)}</small></div>${btn('Start','start-plan-day','','button-primary button-tiny',`data-plan="${esc(p.id)}" data-day="${esc(d.id)}"`)}</div>`).join('')||'<p class="caption">Rest or unscheduled day</p>'}<hr class="tiny-divider"><h4 class="section-label">Nutrition & body</h4><div class="list-row"><div class="list-icon">${icon('utensils')}</div><div class="list-main"><strong>${num(macroTotal(nut).calories)} kcal</strong><small>${nut.length} food entries</small></div></div><div class="list-row"><div class="list-icon">${icon('scale')}</div><div class="list-main"><strong>${body.length?num(body.at(-1).weight,1)+' '+state.settings.unit:'No body check-in'}</strong><small>Body measurements</small></div></div></div></div>`}
function settingsPage(){const s=state.settings;return `${sectionIntro('Settings & backup','Make the workspace yours, set targets and protect your data.')}
<div class="split-2"><div class="panel">${panelHead('Your profile','Personal preferences for training and tracking')}<div class="settings-hero"><div class="settings-avatar">${esc((s.name||'A').charAt(0).toUpperCase())}</div><div><strong style="font:700 18px var(--font-display)">${esc(s.name)}</strong><div class="caption">Personal workspace · English · Offline-first</div></div></div><hr class="tiny-divider"><form id="settingsForm"><div class="field-grid"><div class="field"><label for="settingName">Display name</label><input required id="settingName" name="name" maxlength="40" value="${esc(s.name)}"/></div><div class="field"><label for="settingUnit">Weight unit</label><select id="settingUnit" name="unit"><option value="kg" ${s.unit==='kg'?'selected':''}>Kilograms (kg)</option><option value="lb" ${s.unit==='lb'?'selected':''}>Pounds (lb)</option></select></div><div class="field"><label for="settingHeight">Height (cm)</label><input id="settingHeight" name="height" type="number" min="0" max="250" step="1" value="${esc(s.height||'')}"/></div><div class="field"><label for="settingGoal">Fitness goal</label><select id="settingGoal" name="goal">${['Build muscle','Improve strength','Fat loss','General fitness','Endurance'].map(o=>`<option ${s.goal===o?'selected':''}>${o}</option>`).join('')}</select></div><div class="field"><label for="settingWeekly">Workouts per week</label><input id="settingWeekly" name="weeklyGoal" type="number" min="1" max="7" required value="${esc(s.weeklyGoal)}"/></div><div class="field"><label for="settingTarget">Target body weight (${esc(s.unit)})</label><input id="settingTarget" name="targetWeight" type="number" step="0.1" min="0" max="700" value="${esc(s.targetWeight)}" placeholder="Optional"/></div></div><h4 class="section-label" style="margin-top:19px">Training Intelligence defaults</h4><div class="field-grid cols-3"><div class="field"><label>Available equipment</label><select name="preferredEquipment">${['Full gym','Dumbbells + Bodyweight','Bodyweight only'].map(o=>`<option value="${esc(o)}" ${s.preferredEquipment===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div><div class="field"><label>Progression step (${esc(s.unit)})</label><input name="progressionStep" type="number" min="0.5" max="25" step="0.5" value="${esc(s.progressionStep)}" required/></div><div class="field"><label>Default target RPE</label><select name="targetRPE">${[6,6.5,7,7.5,8,8.5,9].map(n=>`<option value="${n}" ${Number(s.targetRPE)===n?'selected':''}>${n} / 10</option>`).join('')}</select></div></div><h4 class="section-label" style="margin-top:19px">Daily nutrition targets</h4><div class="field-grid cols-4"><div class="field"><label>Calories (kcal)</label><input name="calories" type="number" min="0" max="12000" required value="${esc(s.calories)}"/></div><div class="field"><label>Protein (g)</label><input name="protein" type="number" min="0" max="800" required value="${esc(s.protein)}"/></div><div class="field"><label>Carbs (g)</label><input name="carbs" type="number" min="0" max="1400" required value="${esc(s.carbs)}"/></div><div class="field"><label>Fat (g)</label><input name="fats" type="number" min="0" max="500" required value="${esc(s.fats)}"/></div></div><p class="caption">These are editable tracking targets, not individually prescribed nutrition advice. Changing weight units automatically converts recorded weights and targets.</p><div style="display:flex;gap:9px;margin-top:17px"><button type="submit" class="button button-primary">${icon('save')} Save preferences</button></div></form></div>
<div class="panel">${panelHead('Appearance','A high-contrast workspace that adapts to you')}<div class="field"><label>Color theme</label><div style="display:flex;gap:8px;margin-top:5px">${btn('Midnight dark','select-theme','moon',s.theme==='dark'?'button-primary':'',`data-value="dark"`)}${btn('Clean light','select-theme','sun',s.theme==='light'?'button-primary':'',`data-value="light"`)}</div></div><hr class="tiny-divider">${panelHead('Backup & portability','Your records deserve a safe copy')}<p class="caption">All current workouts, custom exercises, foods, measurements and compressed photos live in this browser. Export a backup periodically, especially before clearing browser data or changing devices.</p><div style="display:flex;gap:9px;flex-wrap:wrap">${btn('Export JSON backup','export-backup','download','button-primary')}${btn('Import JSON backup','import-backup','upload')}</div><input id="importFileInput" type="file" accept="application/json,.json" style="display:none"/><hr class="tiny-divider">${panelHead('Demo & reset','Use examples to explore, then start fresh')}<div style="display:flex;gap:8px;flex-wrap:wrap">${btn('Load sample data','load-demo','sparkles')}${btn('Erase local data','clear-data','trash','button-danger')}</div><div class="sp-18"></div><div class="data-warning"><strong>Cloud sync is optional.</strong> Your data remains local until you configure a separate Supabase project and sign in under Integrations. Progress photos are always local-only, including when cloud records are enabled.</div></div></div>`}
// Modals and input workflows
function modal(title,body,onSubmit=null,opts={}){modalFn=onSubmit;el('modalRoot').className='modal-root visible';el('modalRoot').innerHTML=`<div class="modal-backdrop" data-act="close-modal"></div><section class="modal ${opts.wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><div><h2>${esc(title)}</h2>${opts.sub?`<p>${esc(opts.sub)}</p>`:''}</div><button type="button" class="icon-button" data-act="close-modal" aria-label="Close dialog">${icon('x')}</button></div><form id="modalForm"><div class="modal-body">${body}</div>${opts.hideActions?'':`<div class="modal-actions"><button type="button" class="button" data-act="close-modal">Cancel</button>${onSubmit?`<button type="submit" class="button button-primary">${icon('check',16)} ${esc(opts.saveLabel||'Save changes')}</button>`:''}</div>`}</form></section>`;el('modalRoot').querySelector('input:not([type=hidden]),select,textarea,button')?.focus()}
function closeModal(){modalFn=null;el('modalRoot').className='modal-root';el('modalRoot').innerHTML=''}
function field(name,label,value='',type='text',attrs=''){return `<div class="field"><label for="mf-${name}">${esc(label)}</label><input id="mf-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}/></div>`}
function choiceField(name,label,items,value=''){return `<div class="field"><label for="mf-${name}">${esc(label)}</label><select id="mf-${name}" name="${name}">${items.map(k=>{let v=typeof k==='string'?k:k.value,t=typeof k==='string'?k:k.label;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`}).join('')}</select></div>`}
function fromForm(form){return Object.fromEntries(new FormData(form).entries())}
const EX_OPTIONS=()=>[...state.exercises].sort((a,b)=>a.name.localeCompare(b.name)).map(e=>({value:e.id,label:`${e.name} — ${e.muscle}`}));
function openQuickMenu(){modal('Quick add',`<p class="caption">Choose what you want to track.</p><div class="grid g2">${[['start-workout','dumbbell','Start workout'],['log-food','utensils','Log food'],['body-log','scale','Body measurement'],['photo-log','camera','Progress photo'],['custom-exercise','plus','New exercise'],['add-plan','calendar-range','New plan']].map(([act,ico,label])=>`<button class="button" style="justify-content:flex-start;min-height:57px" type="button" data-act="${act}">${icon(ico)} ${label}</button>`).join('')}</div>`,null,{hideActions:true})}
function startWorkout(title='Free workout',items=[]){if(state.activeSession){setPage('workout');toast('Your current session is already open.');return}set(()=>{state.activeSession={id:id(),title,startedAt:Date.now(),date:ymd(),notes:'',restEndsAt:0,restSeconds:nval(state.settings.defaultRest)||90,exercises:items.map(it=>{const prev=previousSets(it.exerciseId);return {id:id(),exerciseId:it.exerciseId,sets:Array.from({length:clamp(nval(it.sets)||3,1,10)},(_,i)=>({id:id(),weight:it.startWeight??prev[i]?.weight??prev.at(-1)?.weight??0,reps:nval(it.reps)||prev[i]?.reps||10,rpe:'',rir:'',type:'working',done:false}))}})}},'Workout started.');setPage('workout')}
function startPlanDay(pid,did){let p=state.plans.find(p=>p.id===pid),d=p?.days.find(d=>d.id===did);if(!d)return toast('Training day not found.','error');if(state.activeSession){setPage('workout');return toast('Finish or discard your current session first.','error')}const cy=currentCycle(),pres=cy?.planId===pid?cyclePrescription(cy):null;const manualDeload=state.deloadWeeks.includes(startWeek());startWorkout(d.title,d.items.map(x=>({...x,sets:Math.max(1,Math.round(nval(x.sets)*(manualDeload?.65:pres?.volumeFactor||1)))})));if(pres)toast(`Cycle week ${pres.week}: ${pres.phase.toLowerCase()} • set targets adjusted. Review loads and effort.`);else if(manualDeload)toast('Deload week: default set count reduced. Adjust loads and sets as needed.')}
function chooseWorkout(){let p=plan();modal('Choose a workout',`<p class="caption">Choose a training day from your active plan, or start an unplanned session.</p><div class="grid" style="gap:10px">${(p?.days||[]).map(d=>`<button type="button" class="button" style="justify-content:space-between;padding:16px" data-act="start-plan-day" data-plan="${esc(p.id)}" data-day="${esc(d.id)}"><span>${icon('dumbbell')} ${esc(d.title)} · ${d.items.length} exercises</span>${icon('arrow-right')}</button>`).join('')}<button type="button" class="button button-primary" data-act="start-workout">${icon('plus')} Start empty workout</button></div>`,null,{hideActions:true})}
function showStart(){if(state.activeSession){closeModal();setPage('workout');return}modal('Start a workout',`${field('title','Workout name','Free workout','text','required maxlength="70"')}<p class="caption">Start empty, then add exercises during the session. Or use a scheduled day from Training Plans.</p>`,v=>{startWorkout(v.title.trim()||'Free workout')},{saveLabel:'Start workout'})}
function showLiveExercise(){if(!state.activeSession){toast('Start a workout first.','error');return}modal('Add an exercise',`${choiceField('exerciseId','Exercise',EX_OPTIONS())}<div class="field-grid">${field('sets','Number of sets',3,'number','required min="1" max="20"')}${field('reps','Target repetitions',10,'number','required min="1" max="500"')}</div>`,v=>{const prev=previousSets(v.exerciseId);set(()=>{state.activeSession.exercises.push({id:id(),exerciseId:v.exerciseId,sets:Array.from({length:clamp(nval(v.sets),1,20)},(_,i)=>({id:id(),weight:prev[i]?.weight??prev.at(-1)?.weight??0,reps:clamp(nval(v.reps),1,500),rpe:'',done:false}))})},'Exercise added')},{saveLabel:'Add exercise'})}
function confirmModal(title,message,action,label='Confirm',danger=false){modal(title,`<p class="small" style="margin-bottom:8px">${esc(message)}</p>`,()=>action(),{saveLabel:label})}
function finishWorkout(){let a=state.activeSession;if(!a)return;if(totalSets(a)<1){toast('Complete at least one set before finishing.','error');return}modal('Finish your workout',`<div class="panel soft" style="margin-bottom:14px;padding:14px"><div class="workout-total"><div><span class="caption">Completed sets</span><br><strong>${totalSets(a)}</strong></div><div><span class="caption">Training volume</span><br><strong>${num(vol(a))} ${state.settings.unit}</strong></div><div><span class="caption">Elapsed time</span><br><strong>${minutes((Date.now()-a.startedAt)/60000)}</strong></div></div></div><div class="field"> <label>Session notes (optional)</label><textarea name="notes" maxlength="700" placeholder="Energy, technique cues, next-session notes…">${esc(a.notes||'')}</textarea></div>`,v=>{let stopped=Date.now();set(()=>{let w=structuredClone(state.activeSession);w.notes=v.notes.trim();w.endedAt=stopped;w.durationMinutes=Math.max(1,Math.round((stopped-w.startedAt)/60000));w.exercises=w.exercises.map(x=>({...x,sets:x.sets.filter(s=>s.done)})).filter(x=>x.sets.length);state.sessions.push(w);state.activeSession=null},'Workout saved to history!');setPage('workout')},{saveLabel:'Save completed workout'})}
function viewSession(sid){let w=state.sessions.find(w=>w.id===sid);if(!w)return;modal(w.title,`<p class="caption">${fmtDate(w.date,{weekday:'long',month:'long',day:'numeric',year:'numeric'})} · ${minutes(w.durationMinutes)} · ${totalSets(w)} sets · ${num(vol(w))} ${state.settings.unit} volume</p>${w.notes?`<div class="data-warning">${esc(w.notes)}</div>`:''}${w.exercises.map(x=>`<div style="margin-top:19px"><strong style="font:700 15px var(--font-display)">${esc(exercise(x.exerciseId).name)}</strong><div class="table-wrap"><table class="table"><thead><tr><th>Set</th><th>Weight</th><th>Reps</th><th>RPE</th></tr></thead><tbody>${x.sets.map((s,i)=>`<tr><td>${i+1}</td><td>${num(s.weight,1)} ${state.settings.unit}</td><td>${s.reps}</td><td>${s.rpe||'—'}</td></tr>`).join('')}</tbody></table></div></div>`).join('')}<hr class="tiny-divider">${btn('Delete this workout','delete-session','trash','button-danger button-tiny',`data-id="${esc(sid)}"`)}`,null,{wide:true,hideActions:true})}
function planDay(pid,did){let p=state.plans.find(x=>x.id===pid);return p?.days.find(d=>d.id===did)}
function addPlanForm(){modal('Create training plan',`${field('name','Plan name','','text','required maxlength="70"')}${field('description','Description (optional)','','text','maxlength="110"')}<p class="caption">Add days and exercises after creating the plan.</p>`,v=>{let newId=id();set(()=>{state.plans.push({id:newId,name:v.name.trim(),description:v.description.trim(),days:[]});ui.selectedPlanId=newId;state.activePlanId=newId},'Training plan created');setPage('plans')},{saveLabel:'Create plan'})}
function dayForm(pid,did=null){let x=did?planDay(pid,did):null;modal(x?'Edit training day':'Add training day',`${field('title','Workout title',x?.title||'Upper Body','text','required maxlength="65"')}${choiceField('weekday','Weekday',WEEKDAYS.map((w,i)=>({value:String(i),label:w})),String(x?.weekday??1))}`,v=>{set(()=>{if(x){x.title=v.title.trim();x.weekday=Number(v.weekday)}else planFor(pid)?.days.push({id:id(),title:v.title.trim(),weekday:Number(v.weekday),items:[]})},x?'Day updated':'Day added')},{saveLabel:x?'Update day':'Add day'})}
const planFor=pid=>state.plans.find(p=>p.id===pid);
function planExerciseForm(pid,did,iid=null){let day=planDay(pid,did),x=iid?day?.items.find(i=>i.id===iid):null;if(!day)return;modal(x?'Edit planned exercise':'Add planned exercise',`${choiceField('exerciseId','Exercise',EX_OPTIONS(),x?.exerciseId||'') }<div class="field-grid cols-3">${field('sets','Sets',x?.sets||3,'number','min="1" max="20" required')}${field('reps','Target reps',x?.reps||10,'number','min="1" max="500" required')}${field('rest','Rest (seconds)',x?.rest??90,'number','min="0" max="900" required')}${field('startWeight','Optional starting load ('+state.settings.unit+')',x?.startWeight??'','number','min="0" max="1500" step="0.5"')}</div>`,v=>{set(()=>{if(x){Object.assign(x,{exerciseId:v.exerciseId,sets:clamp(nval(v.sets),1,20),reps:clamp(nval(v.reps),1,500),rest:clamp(nval(v.rest),0,900),startWeight:v.startWeight===''?null:clamp(nval(v.startWeight),0,1500)})}else day.items.push({id:id(),exerciseId:v.exerciseId,sets:clamp(nval(v.sets),1,20),reps:clamp(nval(v.reps),1,500),rest:clamp(nval(v.rest),0,900),startWeight:v.startWeight===''?null:clamp(nval(v.startWeight),0,1500)})},x?'Prescription updated':'Exercise added to day')},{saveLabel:x?'Update exercise':'Add to plan'})}
function customExerciseForm(){modal('Create custom exercise',`${field('name','Exercise name','','text','maxlength="80" required')}${choiceField('muscle','Muscle group',muscles,'Chest')}${field('equipment','Equipment','Other','text','maxlength="45" required')}`,v=>{const name=v.name.trim();if(state.exercises.some(e=>e.name.toLowerCase()===name.toLowerCase()))return toast('An exercise with this name already exists.','error');set(()=>state.exercises.push({id:id(),name,muscle:v.muscle,equipment:v.equipment.trim(),custom:true}),'Custom exercise created')},{saveLabel:'Create exercise'})}
function exerciseDetails(exId){let e=exercise(exId),pr=exercisePR(exId),recent=pr.records.slice(-12);modal(e.name,`<p class="caption">${esc(e.muscle)} · ${esc(e.equipment)}${e.custom?' · Custom':''}</p><div class="grid g3" style="margin:16px 0"><div class="panel soft" style="padding:12px"><span class="caption">Best weight</span><div class="num" style="font-size:22px;font-weight:700">${num(pr.weight,1)} <small>${state.settings.unit}</small></div></div><div class="panel soft" style="padding:12px"><span class="caption">Est. 1RM</span><div class="num" style="font-size:22px;font-weight:700">${num(pr.e1rm,1)} <small>${state.settings.unit}</small></div></div><div class="panel soft" style="padding:12px"><span class="caption">Total volume</span><div class="num" style="font-size:22px;font-weight:700">${num(pr.volume)}</div></div></div>${recent.length>=2?lineChart(recent.map(r=>r.weight),{labels:recent.map(r=>fmtDate(r.date)),height:170}):empty('chart-line','No trend yet','Log a few working sets of this movement to see progress.')}<p class="caption">Estimated 1RM uses the Epley formula for sets of 1–12 repetitions. It is an estimate, not a tested maximum.</p><div class="modal-actions">${btn(state.activeSession?'Add to live workout':'Start with this exercise','start-with-exercise','plus','button-primary',`data-id="${esc(exId)}"`)}</div>`,null,{wide:true,hideActions:true})}
function foodForm(savedId=null,templateName=''){let f=state.foods.find(x=>x.id===savedId),m=ui.nutritionDate;modal('Log food',`<div class="field-grid">${field('name','Food / meal name',f?.name||templateName,'text','required maxlength="80"')}${choiceField('meal','Meal',['Breakfast','Lunch','Dinner','Snacks'],'Lunch')}</div><div class="field-grid">${field('date','Date',m,'date','required')}${field('serving','Serving description',f?.serving||'1 serving','text','maxlength="60"')}</div><div class="field-grid cols-4">${field('calories','Calories (kcal)',f?.calories??0,'number','min="0" max="10000" step="0.1" required')}${field('protein','Protein (g)',f?.protein??0,'number','min="0" max="1000" step="0.1" required')}${field('carbs','Carbs (g)',f?.carbs??0,'number','min="0" max="1000" step="0.1" required')}${field('fats','Fat (g)',f?.fats??0,'number','min="0" max="1000" step="0.1" required')}</div><label style="display:flex;align-items:center;gap:9px;margin-top:13px;font-size:12px"><input type="checkbox" name="remember" value="yes" ${f?'':'checked'} /> Save to my food library</label><p class="caption">Enter values for one serving as shown on your food label or recipe. Calories are not auto-derived from macros.</p>`,v=>{let food={name:v.name.trim(),meal:v.meal,date:v.date,serving:v.serving.trim(),calories:nval(v.calories),protein:nval(v.protein),carbs:nval(v.carbs),fats:nval(v.fats)};set(()=>{state.nutrition.push({id:id(),...food});if(v.remember==='yes'&&!state.foods.some(x=>x.name.toLowerCase()===food.name.toLowerCase())){let {meal,date,...base}=food;state.foods.push({id:id(),...base})}ui.nutritionDate=food.date},'Food entry saved')},{saveLabel:'Log food'})}
function savedFoodForm(){modal('Save a food',`${field('name','Food name','','text','required maxlength="80"')}${field('serving','Serving description','1 serving','text','maxlength="60"')}<div class="field-grid cols-4">${field('calories','Calories',0,'number','required min="0" max="10000" step="0.1"')}${field('protein','Protein (g)',0,'number','required min="0" max="1000" step="0.1"')}${field('carbs','Carbs (g)',0,'number','required min="0" max="1000" step="0.1"')}${field('fats','Fat (g)',0,'number','required min="0" max="1000" step="0.1"')}</div>`,v=>{set(()=>state.foods.push({id:id(),name:v.name.trim(),serving:v.serving.trim(),calories:nval(v.calories),protein:nval(v.protein),carbs:nval(v.carbs),fats:nval(v.fats)}),'Saved to food library')},{saveLabel:'Save food'})}
function bodyForm(recordId=null){let x=state.bodyLogs.find(y=>y.id===recordId);const vals=[['weight',`Weight (${state.settings.unit})`],['bodyFat','Body fat (%)'],['chest','Chest (cm)'],['waist','Waist (cm)'],['hips','Hips (cm)'],['arm','Upper arm (cm)'],['thigh','Thigh (cm)']];modal(x?'Edit body check-in':'New body check-in',`${field('date','Date',x?.date||ymd(),'date','required')}<div class="field-grid">${vals.map(([key,label])=>field(key,label,x?.[key]??'','number',`min="0" max="${key==='bodyFat'?100:700}" step="0.1"`)).join('')}</div><div class="field"><label>Notes (optional)</label><textarea name="notes" maxlength="500" placeholder="Measurement conditions, energy, how your clothes fit…">${esc(x?.notes||'')}</textarea></div>`,v=>{let entry={id:x?.id||id(),date:v.date,notes:v.notes.trim()};for(let [key] of vals)entry[key]=v[key]===''?null:nval(v[key]);if(entry.weight==null&&entry.waist==null&&entry.bodyFat==null)return toast('Enter at least one measurement.','error');set(()=>{if(x)Object.assign(x,entry);else state.bodyLogs.push(entry)},'Body check-in saved')},{saveLabel:x?'Update check-in':'Save check-in'})}
function photoForm(){modal('Add progress photo',`${field('date','Photo date',ymd(),'date','required')}<div class="field"><label for="progressPhoto">Choose a photo (JPEG, PNG or WebP)</label><input type="file" name="photo" id="progressPhoto" accept="image/jpeg,image/png,image/webp" required/></div>${field('note','Caption (optional)','','text','maxlength="90"')}<div class="data-warning">Photos are resized for browser storage and included in backup files. Use a private device; these are not uploaded to Supabase.</div>`,async (v,form)=>{if(state.photos.length>=16)return toast('Maximum 16 photos. Delete some before adding more.','error');let f=form.querySelector('input[type=file]').files[0];if(!f||!/^image\/(jpeg|png|webp)$/.test(f.type))return toast('Select a valid JPG, PNG or WebP image.','error');if(f.size>12*1024*1024)return toast('Image must be smaller than 12 MB.','error');try{const data=await compressImage(f);state.photos.push({id:id(),date:v.date,note:v.note.trim(),data});if(!save()){state.photos.pop();return}render();toast('Progress photo saved locally')}catch(e){toast('Could not process the photo.','error')}},{saveLabel:'Save photo'})}
function compressImage(file){return new Promise((resolve,reject)=>{const image=new Image(),url=URL.createObjectURL(file);image.onload=()=>{try{let scale=Math.min(1,700/Math.max(image.width,image.height));let canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));let ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);let data=canvas.toDataURL('image/jpeg',.65);URL.revokeObjectURL(url);resolve(data)}catch(e){URL.revokeObjectURL(url);reject(e)}};image.onerror=()=>{URL.revokeObjectURL(url);reject(new Error('invalid image'))};image.src=url})}
function makeSampleData(){let d=blank();d.settings.demo=true;d.settings.name='Athlete';const demoWeights=[{date:addDays(ymd(),-49),weight:79.2,waist:86.5,chest:101.5,arm:34.5,bodyFat:18.6},{date:addDays(ymd(),-35),weight:78.8,waist:85.5,chest:102,arm:35.0,bodyFat:18.1},{date:addDays(ymd(),-21),weight:78.4,waist:84.6,chest:102.5,arm:35.2,bodyFat:17.8},{date:addDays(ymd(),-7),weight:78.0,waist:83.7,chest:103.1,arm:35.5,bodyFat:17.5}];d.bodyLogs=demoWeights.map(x=>({id:id(),...x,hips:null,thigh:null,notes:'Sample measurement'}));let p=d.plans[0];for(let week=5;week>=0;week--)for(let i=0;i<3;i++){let day=p.days[i],start=addDays(startWeek(),-week*7+(day.weekday+6)%7);if(start>ymd())continue;let t=Date.now()-(week*7+4)*86400000+i*86400000;d.sessions.push({id:id(),title:day.title,startedAt:t,endedAt:t+53*60000,date:start,durationMinutes:53,notes:'Example session — delete or reset when ready',exercises:day.items.slice(0,4).map((it,j)=>({id:id(),exerciseId:it.exerciseId,sets:Array.from({length:3},(_,k)=>({id:id(),weight:Math.round((j===0?60:20)+(5-week)*1.25+k*2.5),reps:it.reps,rpe:7.5,done:true}))}))})}
d.weeklyCheckins=[{id:id(),weekStart:startWeek(),sleep:4,energy:4,fatigue:2,soreness:2,stress:2,appetite:3,adherence:80,bodyweight:78.0,notes:'Sample check-in; replace with your own ratings.'}];d.trainingCycles=[{id:'sample-cycle',name:'Example 6-week block',planId:d.activePlanId,startDate:addDays(startWeek(),-14),weeks:6,targetRPE:8,createdAt:Date.now()}];d.activeCycleId='sample-cycle';const foodNames=[['Greek yogurt',130,15,10,3,'Breakfast'],['Chicken and rice',580,44,66,12,'Lunch'],['Egg sandwich',340,22,32,13,'Dinner'],['Fruit snack',150,2,35,1,'Snacks']];for(let offset=0;offset<6;offset++){let date=addDays(ymd(),-offset);for(let food of foodNames){d.nutrition.push({id:id(),date,name:food[0],serving:'1 serving',calories:food[1],protein:food[2],carbs:food[3],fats:food[4],meal:food[5]})}}d.foods=foodNames.map(f=>({id:id(),name:f[0],serving:'1 serving',calories:f[1],protein:f[2],carbs:f[3],fats:f[4]}));return d}
function exportBackup(){const raw=JSON.stringify(state,null,2),blob=new Blob([raw],{type:'application/json;charset=utf-8'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=`OS_Fit_Backup_${ymd()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1800);toast('JSON backup downloaded')}
async function restoreBackup(file){if(!file)return;if(file.size>16*1024*1024)return toast('Backup exceeds the 16 MB import limit.','error');let raw;try{raw=JSON.parse(await file.text())}catch{return toast('This is not a readable JSON backup.','error')}if(!isValid(raw))return toast('Invalid or unsupported OS Fit V1 backup.','error');if(raw.photos.some(p=>!String(p.data||'').startsWith('data:image/jpeg;base64,')))return toast('Backup contains an unsupported photo format.','error');confirmModal('Restore backup?','This replaces local workouts, nutrition, measurements and photos. If cloud sync is connected, restored data may also sync to your account. Export a backup first.',()=>{state=normalizeExtras(raw);ui.page='dashboard';ui.selectedPlanId=state.activePlanId;ui.exerciseSearch='';ui.calendarMonth=ymd().slice(0,7);save();setPage('dashboard');toast('Backup restored successfully')},'Restore backup',true)}
function toggleTheme(){set(()=>state.settings.theme=state.settings.theme==='light'?'dark':'light')}
function saveSettings(form){let v=fromForm(form);const from=state.settings.unit,to=v.unit;if(from!==to){const factor=from==='kg'?2.2046226218:1/2.2046226218;const convert=x=>x===null||x===''||x===undefined?x:Math.round(nval(x)*factor*100)/100;for(let w of [...state.sessions,...(state.activeSession?[state.activeSession]:[])])for(let e of w.exercises||[])for(let s of e.sets||[])s.weight=convert(s.weight);for(let b of state.bodyLogs)b.weight=convert(b.weight);for(let p of state.plans)for(let d of p.days)for(let x of d.items)if(x.startWeight!==undefined&&x.startWeight!==null)x.startWeight=convert(x.startWeight);for(let x of state.weeklyCheckins)if(x.bodyweight!=null)x.bodyweight=convert(x.bodyweight);state.settings.progressionStep=convert(state.settings.progressionStep);state.settings.targetWeight=convert(state.settings.targetWeight)}
let ageOfTarget=v.targetWeight===''?'':nval(v.targetWeight);set(()=>{Object.assign(state.settings,{name:v.name.trim()||'Athlete',unit:v.unit,height:nval(v.height),goal:v.goal,weeklyGoal:clamp(nval(v.weeklyGoal),1,7),preferredEquipment:v.preferredEquipment,progressionStep:clamp(nval(v.progressionStep)*(from===to?1:from==='kg'?2.2046226218:1/2.2046226218),.5,25),targetRPE:clamp(nval(v.targetRPE),6,9),targetWeight:from!==to?state.settings.targetWeight===''?ageOfTarget:state.settings.targetWeight:ageOfTarget,calories:nval(v.calories),protein:nval(v.protein),carbs:nval(v.carbs),fats:nval(v.fats)})},'Preferences saved')}
function updateTimers(){const a=state.activeSession;if(!a)return;let sec=Math.max(0,Math.floor((Date.now()-a.startedAt)/1000));for(let e of document.querySelectorAll('[data-timer="elapsed"]'))e.textContent=`${pad(Math.floor(sec/3600))}:${pad(Math.floor((sec%3600)/60))}:${pad(sec%60)}`;let rest=Math.max(0,Math.ceil(((a.restEndsAt||0)-Date.now())/1000));for(let e of document.querySelectorAll('[data-timer="rest"]'))e.textContent=rest?`${pad(Math.floor(rest/60))}:${pad(rest%60)}`:'—'}
// ── OS Fit V2 • coaching, training analytics, nutrition and wellness ──────────
const workSets=w=>(w.exercises||[]).flatMap(x=>(x.sets||[]).filter(s=>s.done && (s.type||'working')!=='warmup').map(s=>({exerciseId:x.exerciseId,...s})));
const visibleRangeDays=()=>ui.analyticsWindow||28;
function muscleTotals(days=28,end=ymd()){
 const start=addDays(end,-days+1),o=Object.fromEntries(muscles.map(m=>[m,{sets:0,volume:0,exercises:new Set()}]));
 for(const w of state.sessions.filter(x=>x.date>=start&&x.date<=end))for(const x of w.exercises||[]){const e=exercise(x.exerciseId),m=o[e.muscle]||o.Core;for(const s of x.sets||[]){if(!s.done || (s.type||'working')==='warmup')continue;m.sets++;m.volume+=nval(s.weight)*nval(s.reps);m.exercises.add(e.id)}}
 return o;
}
function muscleHeatmap(){const a=muscleTotals(7);const op=k=>String(Math.min(.97,Math.max(.13,(a[k]?.sets||0)/14)));const shape=(x,y,w,h,m,rx=9)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="var(--accent)" fill-opacity="${op(m)}" stroke="var(--accent)" stroke-opacity=".40"><title>${m}: ${a[m]?.sets||0} working sets in 7 days</title></rect>`;
 return `<div class="heatmap-grid"><div class="heatmap-body"><span class="caption">FRONT</span><svg viewBox="0 0 180 310" role="img" aria-label="Front muscle activity for last 7 days"><circle cx="90" cy="24" r="18" fill="var(--muted)" fill-opacity=".28"/>${shape(66,47,48,12,'Shoulders',7)}${shape(59,63,30,48,'Chest')}${shape(91,63,30,48,'Chest')}${shape(44,72,14,72,'Arms')}${shape(122,72,14,72,'Arms')}${shape(66,115,48,54,'Core')}${shape(65,173,24,109,'Legs')}${shape(91,173,24,109,'Legs')}</svg></div><div class="heatmap-body"><span class="caption">BACK</span><svg viewBox="0 0 180 310" role="img" aria-label="Back muscle activity for last 7 days"><circle cx="90" cy="24" r="18" fill="var(--muted)" fill-opacity=".28"/>${shape(65,47,50,12,'Shoulders',7)}${shape(59,63,62,92,'Back')}${shape(44,72,14,72,'Arms')}${shape(122,72,14,72,'Arms')}${shape(66,155,48,18,'Core')}${shape(65,175,24,107,'Legs')}${shape(91,175,24,107,'Legs')}</svg></div></div>`;
}
function analyticsPage(){const totals=muscleTotals(visibleRangeDays()),last7=muscleTotals(7),last28=muscleTotals(28);let volume=Object.values(totals).reduce((a,x)=>a+x.volume,0),sets=Object.values(totals).reduce((a,x)=>a+x.sets,0);
 const weeks=Array.from({length:8},(_,i)=>{const e=addDays(startWeek(),(i-7)*7+6);const t=muscleTotals(7,e);return {label:fmtDate(addDays(e,-6),{month:'short',day:'numeric'}),volume:Object.values(t).reduce((n,x)=>n+x.volume,0)}});
 return `${sectionIntro('Muscle analytics','Working-set distribution, recovery context and volume over time. These are tracking indicators, not recovery diagnoses.',btn('Open Smart Coach','go-coach','sparkles','button-primary'))}${liveBanner()}
 <div class="grid g4">${statCard('Working sets',sets,'Excludes warm-up sets','dumbbell')}${statCard('Training volume',num(volume)+' '+esc(state.settings.unit),'Weight × reps','activity')}${statCard('Training days',state.sessions.filter(x=>x.date>=addDays(ymd(),-visibleRangeDays()+1)).length,'Completed sessions','calendar-check')}${statCard('Muscles tracked',Object.values(totals).filter(x=>x.sets>0).length,'Muscle groups active','target')}</div><div class="sp-18"></div>
 <div class="split-2"><div class="panel">${panelHead('Muscle heatmap','Weekly working-set activity · illustrative body diagram')}${muscleHeatmap()}<p class="caption">Higher opacity means more recorded sets. Individual recovery varies; this is not an anatomical or injury assessment.</p></div><div class="panel">${panelHead('Working sets by muscle','Change the analysis window',`<select class="select-control" data-ui-field="analyticsWindow"><option value="7" ${visibleRangeDays()==7?'selected':''}>Last 7 days</option><option value="28" ${visibleRangeDays()==28?'selected':''}>Last 28 days</option><option value="84" ${visibleRangeDays()==84?'selected':''}>Last 84 days</option></select>`)}${muscles.map(m=>{const x=totals[m],max=Math.max(1,...Object.values(totals).map(z=>z.sets));return `<div class="muscle-row"><div class="muscle-top"><strong>${m}</strong><span>${x.sets} sets · ${num(x.volume)} ${esc(state.settings.unit)}</span></div><div class="progress-track"><div class="progress-fill" style="width:${(x.sets/max*100).toFixed(1)}%"></div></div></div>`}).join('')}</div></div>
 <div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Volume trend','Eight rolling training weeks')}${barChart(weeks.map(w=>w.volume),weeks.map(w=>w.label))}</div><div class="panel">${panelHead('Weekly workload review','A descriptive comparison, not a prescription')}${muscles.filter(m=>last7[m].sets||last28[m].sets).map(m=>`<div class="list-row"><div class="list-main"><strong>${m}</strong><small>Current 7 days vs prior 28-day average / week</small></div><div class="list-right">${last7[m].sets} / ${num(last28[m].sets/4,1)} sets</div></div>`).join('')||empty('activity','Start logging sets','Your muscle-volume report will appear here.')}</div></div>`;
}
function readinessFor(day=ymd()){return state.readiness.filter(x=>x.date===day).at(-1)}
function coachInsights(){let insights=[];const current=weeklySessions(),prevStart=addDays(startWeek(),-7),previous=state.sessions.filter(x=>x.date>=prevStart&&x.date<startWeek());const count=current.length,goal=nval(state.settings.weeklyGoal)||4;
 if(!state.sessions.length)insights.push({title:'Start with your first logged session',detail:'Record sets, load and repetitions to unlock personalized progression suggestions.',kind:'Setup'});
 else if(count>=goal)insights.push({title:'Weekly attendance goal achieved',detail:`You completed ${count} sessions against a target of ${goal}. Consider your recovery and your planned rest days.`,kind:'Consistency'});
 else insights.push({title:`${Math.max(0,goal-count)} sessions to your weekly goal`,detail:`You have logged ${count} sessions this week. Rearrange your plan if your schedule changes.`,kind:'Consistency'});
 const r=readinessFor();if(r){const low=nval(r.sleep)<=2||nval(r.energy)<=2||nval(r.soreness)>=4;if(low)insights.push({title:'Low readiness check-in',detail:'You reported lower energy/sleep or higher soreness. Consider technique-focused work, reducing volume, or resting if needed.',kind:'Recovery'});else insights.push({title:'Readiness recorded',detail:'Use your sleep, energy and soreness trends alongside completed sets, rather than treating a single number as a diagnosis.',kind:'Recovery'});}else insights.push({title:'Log today’s readiness',detail:'A quick sleep, energy and soreness check-in helps add context to future workout comparisons.',kind:'Recovery'});
 if(previous.length&&count){const a=current.reduce((z,w)=>z+vol(w),0),b=previous.reduce((z,w)=>z+vol(w),0);if(b>0){const delta=100*(a-b)/b;insights.push({title:'Volume compared with last week',detail:`Recorded volume is ${delta>=0?'+':''}${num(delta,0)}% versus the prior calendar week. Set count, exercise choice and technique also matter.`,kind:'Workload'});}}
 const w=[...state.bodyLogs].filter(x=>x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date));if(w.length>=3){const first=w.at(-3).weight,last=w.at(-1).weight;insights.push({title:'Body-weight direction',detail:`Across your latest three entries, weight moved ${last>=first?'+':''}${num(last-first,1)} ${state.settings.unit}. Compare multi-day averages to reduce noise.`,kind:'Body progress'});}
 const logged=Array.from({length:7},(_,i)=>addDays(ymd(),-i)).filter(d=>nutritionDay(d).length>0).length;if(logged<4)insights.push({title:'More nutrition history improves trends',detail:`Food was logged on ${logged} of the last 7 days. Days without entries are unknown, not zero-calorie days.`,kind:'Nutrition'});
 return insights;
}
function suggestions(){let out=[];for(const e of state.exercises){const last=[...state.sessions].sort((a,b)=>(b.endedAt||0)-(a.endedAt||0)).flatMap(w=>w.exercises.filter(x=>x.exerciseId===e.id)).slice(0,2);if(!last.length)continue;let sets=last[0].sets.filter(s=>s.done&&(s.type||'working')!=='warmup'&&nval(s.reps)>0);if(!sets.length)continue;const best=sets.reduce((p,c)=>nval(c.weight)>nval(p.weight)?c:p),step=nval(state.settings.progressionStep)||2.5,target=(plan()?.days||[]).flatMap(d=>d.items).find(x=>x.exerciseId===e.id)?.reps||10;const maxRpe=Math.max(...sets.map(x=>nval(x.rpe)||7));let text='',tag='Consistency';
 if(sets.length>=2&&sets.every(s=>nval(s.reps)>=target)&&maxRpe<=8.5&&nval(best.weight)>0){text=`Consider ${num(nval(best.weight)+step,1)} ${state.settings.unit} next time if technique and effort allow; aim for ${Math.max(5,target-2)}–${target} reps.`;tag='Load option';}
 else if(sets.some(s=>nval(s.reps)<target))text=`Keep your current load and aim for up to ${target} controlled reps in the target sets.`;
 else text='Repeat the load with steady technique or add one rep, rather than rushing a weight increase.';
 out.push({e,tag,text,weight:best.weight,reps:best.reps,date:last[0].date||''});}
 return out.sort((a,b)=>a.e.name.localeCompare(b.e.name));
}
function coachPage(){const insights=coachInsights(),p=suggestions(),r=readinessFor();return `${sectionIntro('Smart Coach','Rule-based training insights derived from your logs. Every suggestion is optional and editable.',btn(r?'Update readiness':'Log readiness','readiness-form','heart','button-primary')+btn('View muscle volume','go-analytics','activity'))}${liveBanner()}
 <div class="grid g4">${statCard('Insights',insights.length,'Based on available records','sparkles')}${statCard('Exercises analyzed',p.length,'Exercises with logged sets','dumbbell')}${statCard('Readiness today',r?`${nval(r.energy)}/5`:'—',r?'Energy check-in':'Not logged yet','heart')}${statCard('Progression increment',`${num(state.settings.progressionStep,1)} ${state.settings.unit}`,'User-defined option','target')}</div><div class="sp-18"></div>
 <div class="split-2"><div class="panel">${panelHead('Your coaching feed','No AI diagnosis or automatic workout changes')}${insights.map(x=>`<div class="insight-card"><span class="pill">${esc(x.kind)}</span><h4>${esc(x.title)}</h4><p>${esc(x.detail)}</p></div>`).join('')}</div><div class="panel">${panelHead('Next-session progression','Recent completed working sets only')}${p.length?p.slice(0,12).map(x=>`<div class="insight-card"><div class="muscle-top"><strong>${esc(x.e.name)}</strong><span class="pill">${esc(x.tag)}</span></div><p><strong>${num(x.weight,1)} ${state.settings.unit} × ${x.reps}</strong> previously · ${esc(x.text)}</p></div>`).join(''):empty('dumbbell','No progression history yet','Complete workouts to receive optional suggestions based on your actual sets.')}</div></div>
 <div class="sp-18"></div><div class="panel">${panelHead('Readiness & recovery context','Self-reported sleep, energy, soreness and stress')}${state.readiness.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Sleep</th><th>Energy</th><th>Soreness</th><th>Stress</th><th></th></tr></thead><tbody>${[...state.readiness].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,14).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${x.sleep}/5</td><td>${x.energy}/5</td><td>${x.soreness}/5</td><td>${x.stress}/5</td><td><button class="button button-tiny" data-act="remove-readiness" data-id="${esc(x.id)}">Remove</button></td></tr>`).join('')}</tbody></table></div>`:empty('heart','No readiness logs','Track how you feel before and after sessions.','readiness-form','Add check-in')}</div>`;}
function readinessForm(){const r=readinessFor();modal('Daily readiness check-in',`${field('date','Date',ymd(),'date','required')}${choiceField('sleep','Sleep quality (1–5)',[1,2,3,4,5].map(n=>({value:String(n),label:`${n} / 5` })),String(r?.sleep||3))}${choiceField('energy','Energy (1–5)',[1,2,3,4,5].map(n=>({value:String(n),label:`${n} / 5`})),String(r?.energy||3))}${choiceField('soreness','Muscle soreness (1–5)',[1,2,3,4,5].map(n=>({value:String(n),label:`${n} / 5`})),String(r?.soreness||2))}${choiceField('stress','Stress (1–5)',[1,2,3,4,5].map(n=>({value:String(n),label:`${n} / 5`})),String(r?.stress||2))}${field('notes','Notes (optional)','','text','maxlength="160"')}`,v=>set(()=>{state.readiness=state.readiness.filter(x=>x.date!==v.date);state.readiness.push({id:id(),date:v.date,sleep:+v.sleep,energy:+v.energy,soreness:+v.soreness,stress:+v.stress,notes:v.notes.trim()})},'Readiness saved'),{saveLabel:'Save readiness'});}
function reportStats(start){const end=addDays(start,6),ss=state.sessions.filter(x=>x.date>=start&&x.date<=end),ns=state.nutrition.filter(x=>x.date>=start&&x.date<=end);const days=[...new Set(ns.map(n=>n.date))],nutrition=macroTotal(ns),b=state.bodyLogs.filter(x=>x.date>=start&&x.date<=end&&x.weight!=null).sort((a,b)=>a.date.localeCompare(b.date));return {start,end,sessions:ss.length,sets:ss.reduce((a,x)=>a+totalSets(x),0),volume:ss.reduce((a,x)=>a+vol(x),0),loggedDays:days.length,avgCalories:days.length?nutrition.calories/days.length:null,avgProtein:days.length?nutrition.protein/days.length:null,bodyFirst:b[0]?.weight,bodyLast:b.at(-1)?.weight};}
function reportPage(){const cur=reportStats(ui.reportWeek),prev=reportStats(addDays(ui.reportWeek,-7)),goal=nval(state.settings.weeklyGoal)||4,work=state.sessions.filter(x=>x.date>=cur.start&&x.date<=cur.end),r=state.readiness.filter(x=>x.date>=cur.start&&x.date<=cur.end);return `${sectionIntro('Weekly performance report','Compare attendance, working sets, nutrition logging, body weight and readiness.',btn('Download CSV','report-csv','download','button-primary')+btn('Print / PDF','report-print','save'))}<div class="filter-row">${btn('Previous week','report-prev','chevron-left','button-tiny')}<span class="panel-badge">${fmtDate(cur.start)} – ${fmtDate(cur.end)}</span>${btn('Next week','report-next','chevron-right','button-tiny')}${btn('Current week','report-current','calendar-days','button-tiny')}</div>
 <div class="grid g4">${statCard('Training sessions',`${cur.sessions}/${goal}`,`${num(cur.sessions-prev.sessions,0)} vs previous week`,'calendar-check')}${statCard('Working sets',cur.sets,`${cur.sets-prev.sets>=0?'+':''}${cur.sets-prev.sets} vs previous week`,'dumbbell')}${statCard('Total volume',num(cur.volume),`${cur.volume>=prev.volume?'+':''}${num(cur.volume-prev.volume)} ${state.settings.unit} vs last week`,'activity')}${statCard('Nutrition days',`${cur.loggedDays}/7`,'Days actually logged','utensils')}</div><div class="sp-18"></div>
 <div class="split-2"><div class="panel">${panelHead('Week at a glance','Attendance goal progress')}${donut(cur.sessions,goal,'workouts')}<div class="list-row"><div class="list-main"><strong>Average logged calories</strong><small>Logged days only; excludes unknown days</small></div><div class="list-right">${cur.avgCalories==null?'—':num(cur.avgCalories)+' kcal'}</div></div><div class="list-row"><div class="list-main"><strong>Average logged protein</strong><small>Logged days only</small></div><div class="list-right">${cur.avgProtein==null?'—':num(cur.avgProtein)+' g'}</div></div><div class="list-row"><div class="list-main"><strong>Body-weight movement</strong></div><div class="list-right">${cur.bodyFirst!=null&&cur.bodyLast!=null?num(cur.bodyLast-cur.bodyFirst,1)+' '+esc(state.settings.unit):'Not enough check-ins'}</div></div></div><div class="panel">${panelHead('Workout breakdown','Completed session summary')}${work.length?work.map(w=>`<div class="list-row"><div class="list-icon">${icon('dumbbell')}</div><div class="list-main"><strong>${esc(w.title)}</strong><small>${fmtDate(w.date)} · ${minutes(w.durationMinutes)}</small></div><div class="list-right">${totalSets(w)} sets</div></div>`).join(''):empty('calendar-days','No workouts logged','A session completed this week will show here.')}</div></div><div class="sp-18"></div><div class="panel">${panelHead('Interpretation','The numbers describe recorded activity, not a medical assessment')}${coachInsights().slice(0,4).map(x=>`<div class="insight-card"><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div>`).join('')}<p class="caption">Readiness check-ins this week: ${r.length}. Logged nutrition is a partial diary, not proof of total intake.</p></div>`;}
function exportCSV(){let cur=reportStats(ui.reportWeek),rows=[['metric','value','unit'],['week_start',cur.start,''],['week_end',cur.end,''],['sessions',cur.sessions,''],['working_sets',cur.sets,''],['training_volume',cur.volume,state.settings.unit],['nutrition_days_logged',cur.loggedDays,''],['average_logged_calories',cur.avgCalories??'','kcal'],['average_logged_protein',cur.avgProtein??'','g']];let content=rows.map(row=>row.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');downloadFile(content,`OS_Fit_Week_${cur.start}.csv`,'text/csv;charset=utf-8');toast('Report downloaded');}
function downloadFile(content,filename,mime='application/json'){let b=new Blob([content],{type:mime}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function recipeNutrition(rec,portions=1){const totals={calories:0,protein:0,carbs:0,fats:0};for(const entry of rec.ingredients||[]){let f=state.foods.find(z=>z.id===entry.foodId)||entry.snapshot;if(!f)continue;for(const key of Object.keys(totals))totals[key]+=nval(f[key])*nval(entry.quantity||1)}for(const k of Object.keys(totals))totals[k]=Math.round(totals[k]*(portions/(nval(rec.servings)||1))*10)/10;return totals}
function recipesPanel(){return `<div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Recipe builder','Combine saved-food servings into reusable recipes',btn('New recipe','recipe-add','plus','button-tiny'))}${state.recipes.length?state.recipes.map(r=>{const v=recipeNutrition(r,1);return `<div class="list-row"><div class="list-icon">${icon('utensils')}</div><div class="list-main"><strong>${esc(r.name)}</strong><small>Per portion: ${num(v.calories)} kcal · P ${num(v.protein)}g · C ${num(v.carbs)}g · F ${num(v.fats)}g</small></div><div class="list-right">${btn('Log','recipe-log','','button-tiny',`data-id="${esc(r.id)}"`)}${btn('Delete','recipe-delete','trash','button-tiny',`data-id="${esc(r.id)}"`)}</div></div>`}).join(''):empty('utensils','No recipes yet','Save foods with their label values, then combine them into recipes.')}</div><div class="panel">${panelHead('Macro target check','Nutrition targets remain fully editable')}<div class="list-row"><div class="list-main"><strong>Energy from planned macros</strong><small>Calculated as 4 kcal/g protein and carbohydrate; 9 kcal/g fat</small></div><div class="list-right">${num(nval(state.settings.protein)*4+nval(state.settings.carbs)*4+nval(state.settings.fats)*9)} kcal</div></div><div class="list-row"><div class="list-main"><strong>Your energy target</strong><small>Set it yourself in Settings</small></div><div class="list-right">${num(state.settings.calories)} kcal</div></div><div class="data-warning">Egyptian dishes can be logged using your own verified package labels or weighed recipe ingredients. No unverified nutrition estimates are pre-filled.</div><div class="sp-18"></div><p class="caption">Quick-start Egyptian food names (enter your own macros):</p><div class="egyptian-chips">${['Ful medames','Ta’ameya','Koshari','Molokhia','Baladi bread','Grilled kofta','Rice and chicken'].map(x=>btn(x,'egyptian-food','','button-tiny',`data-food="${esc(x)}"`)).join('')}</div></div></div>`}
function recipeForm(){if(!state.foods.length)return toast('Save a food first. Recipe calculations use your saved foods.','error');let options=[{value:'',label:'None'},...state.foods.map(f=>({value:f.id,label:f.name}))];modal('Create reusable recipe',`${field('name','Recipe name','','text','required maxlength="80"')}${field('servings','Recipe makes (portions)',2,'number','required min="1" max="100"')}<p class="caption">Choose up to four saved-food ingredients. Quantities use the serving described on each saved food.</p>${[0,1,2,3].map(i=>`<div class="field-grid">${choiceField('ingredient'+i,`Ingredient ${i+1}`,options,'')}${field('qty'+i,'Number of saved-food servings',1,'number','min="0.1" max="100" step="0.1"')}</div>`).join('')}`,v=>{const ingredients=[0,1,2,3].filter(i=>v['ingredient'+i]).map(i=>({foodId:v['ingredient'+i],quantity:clamp(nval(v['qty'+i]),.1,100)}));if(!ingredients.length)return toast('Select at least one ingredient.','error'),false;set(()=>state.recipes.push({id:id(),name:v.name.trim(),servings:nval(v.servings),ingredients}),'Recipe saved')},{saveLabel:'Save recipe',wide:true});}
function logRecipe(rid){let r=state.recipes.find(x=>x.id===rid);if(!r)return;modal(`Log ${r.name}`,`${field('date','Date',ui.nutritionDate,'date','required')}${choiceField('meal','Meal',['Breakfast','Lunch','Dinner','Snacks'],'Lunch')}${field('portions','Portions eaten',1,'number','required min="0.1" max="30" step="0.1"')}`,v=>{const macros=recipeNutrition(r,nval(v.portions));set(()=>{state.nutrition.push({id:id(),name:r.name,date:v.date,meal:v.meal,serving:`${v.portions} portions`,...macros,recipeId:r.id});ui.nutritionDate=v.date},'Recipe logged')},{saveLabel:'Log recipe'});}
function weightAverage(windowSize=7,until=ymd()){let start=addDays(until,-windowSize+1),xs=state.bodyLogs.filter(x=>x.date>=start&&x.date<=until&&x.weight!=null);return xs.length?xs.reduce((a,x)=>a+nval(x.weight),0)/xs.length:null}
function bodyComparisonPanel(){let photos=[...state.photos].sort((a,b)=>a.date.localeCompare(b.date));let left=photos.find(x=>x.id===ui.compareLeft)||photos[0],right=photos.find(x=>x.id===ui.compareRight)||photos.at(-1);const opts=x=>photos.map(p=>`<option value="${esc(p.id)}" ${x?.id===p.id?'selected':''}>${fmtDate(p.date)} · ${esc(p.note||'Progress photo')}</option>`).join('');const weight=weightAverage(),prior=weightAverage(7,addDays(ymd(),-7));return `<div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Seven-day weight average','Smooth daily weight fluctuation')}${weight==null?empty('scale','Add weight check-ins','Daily weigh-ins give the most useful smoothing.'): `<div class="stat-value">${num(weight,2)} ${esc(state.settings.unit)}</div><p class="caption">${prior==null?'Not enough records for previous-week comparison':`${weight-prior>0?'+':''}${num(weight-prior,2)} ${esc(state.settings.unit)} vs previous seven-day window`}</p>`}</div><div class="panel">${panelHead('Progress photo comparison','Selected photos stay on this browser')}${photos.length<2?empty('camera','Add two photos','Take two check-in photos to compare your progress side by side.'):`<div class="field-grid"> <div class="field"><label>Before</label><select class="select-control" data-ui-field="compareLeft">${opts(left)}</select></div><div class="field"><label>After</label><select class="select-control" data-ui-field="compareRight">${opts(right)}</select></div></div><div class="comparison-grid"><figure><img src="${esc(left.data)}" alt="Selected before progress photo"><figcaption>${fmtDate(left.date)}</figcaption></figure><figure><img src="${esc(right.data)}" alt="Selected after progress photo"><figcaption>${fmtDate(right.date)}</figcaption></figure></div>`}</div></div>`;}
function rescheduleForm(){let p=plan();if(!p?.days.length)return toast('Create a training day first.','error');const options=p.days.map(d=>({value:d.id,label:`${d.title} (${WEEKDAYS[d.weekday]})`}));modal('Reschedule a planned day',`${choiceField('dayId','Training day',options)}${field('date','New training date',ymd(),'date','required')}<p class="caption">Only moves the selected occurrence in its week; does not permanently change the plan. The day appears in the training calendar.</p>`,v=>{const d=p.days.find(x=>x.id===v.dayId);if(!d)return false;const newDay=v.date,week=startWeek(newDay);set(()=>{state.reschedules=state.reschedules.filter(x=>!(x.dayId===d.id&&x.planId===p.id&&x.originalWeek===week));state.reschedules.push({id:id(),dayId:d.id,planId:p.id,originalWeek:week,date:newDay})},'Training day rescheduled')},{saveLabel:'Move this session'});}
function toggleDeload(){let week=startWeek(),has=state.deloadWeeks.includes(week);return set(()=>{state.deloadWeeks=state.deloadWeeks.filter(x=>x!==week);if(!has)state.deloadWeeks.push(week)},has?'Deload marker removed':'Current week marked as deload. Planned sessions will use fewer sets.');}
function plateCalculator(){modal('Barbell plate calculator',`${field('target','Total target load ('+state.settings.unit+')',60,'number','required min="0" max="700" step="0.5"')}${field('bar','Bar weight ('+state.settings.unit+')',state.settings.unit==='kg'?20:45,'number','required min="0" max="100" step="0.5"')}<p class="caption">Assumes identical plates on each side, using common denominations for your selected unit. Actual plate availability varies.</p>`,v=>{let target=nval(v.target),bar=nval(v.bar);if(target<bar)return toast('Target must be at least the bar weight.','error'),false;const denom=state.settings.unit==='kg'?[25,20,15,10,5,2.5,1.25,.5,.25]:[45,35,25,10,5,2.5,1.25];let remain=(target-bar)/2,parts=[];for(const d of denom){const n=Math.floor((remain+1e-8)/d);if(n){parts.push(`${n} × ${d} ${state.settings.unit}`);remain=Math.round((remain-n*d)*10000)/10000}}modal('Plate loading result',`<div class="panel soft"><h3>Each side</h3><p class="stat-value">${parts.length?esc(parts.join(' + ')):'No plates'}</p><p class="caption">Total: ${num(target-remain*2,2)} ${esc(state.settings.unit)} including ${num(bar)} ${esc(state.settings.unit)} bar.</p>${remain>.01?`<div class="data-warning">Closest configuration is ${num(remain*2,2)} ${esc(state.settings.unit)} below target.</div>`:''}</div>`,null,{hideActions:true});return false;},{saveLabel:'Calculate'});}
function csvParse(text){let rows=[],row=[],value='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(value);value=''}else if((c==='\r'||c==='\n')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);value='';if(row.some(v=>v!==''))rows.push(row);row=[]}else value+=c}row.push(value);if(row.some(v=>v!==''))rows.push(row);return rows}
async function importWearableCsv(file){if(!file)return;if(file.size>1024*1024)return toast('CSV must be under 1 MB.','error');let rows=csvParse(await file.text());if(rows.length<2||rows.length>1501)return toast('CSV needs 1–1,500 data rows.','error');let head=rows.shift().map(x=>x.trim().toLowerCase().replace(/[^a-z0-9]+/g,'_'));let index=Object.fromEntries(head.map((x,i)=>[x,i]));if(index.date==null)return toast('CSV requires a date column (YYYY-MM-DD).','error');const fields=['steps','sleep_hours','resting_hr','weight'];if(!fields.some(f=>index[f]!=null))return toast('CSV needs steps, sleep_hours, resting_hr or weight column.','error');let parsed=rows.map(r=>{let entry={date:(r[index.date]||'').trim()};for(const k of fields)if(index[k]!=null){let v=(r[index[k]]||'').trim();entry[k]=v===''?null:Number(v)}return entry}).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&!Number.isNaN(dateOf(x.date).getTime())&&fields.some(k=>Number.isFinite(x[k])&&x[k]>=0));if(!parsed.length)return toast('No valid dated measurements found.','error');if(parsed.some(x=>x.weight!=null&&x.weight>700))return toast('Weight values appear invalid; check your chosen unit.','error');confirmModal('Import wearable CSV?',`Import ${parsed.length} valid daily records. Weight rows will also be added as body check-ins when no weight is recorded on that date. All data stays in this browser unless you separately enable cloud sync.`,()=>set(()=>{for(const x of parsed){const old=state.wearables.find(z=>z.date===x.date);if(old)Object.assign(old,x);else state.wearables.push({id:id(),...x});if(x.weight!=null&&!state.bodyLogs.some(z=>z.date===x.date&&z.weight!=null))state.bodyLogs.push({id:id(),date:x.date,weight:x.weight,notes:'Imported from wearable CSV'})}},`${parsed.length} wearable records imported`),'Import records');}
function integrationsPage(){let rows=[...state.wearables].sort((a,b)=>b.date.localeCompare(a.date));return `${sectionIntro('Connected fitness','Portable, privacy-aware imports now; native HealthKit and wearable APIs require separate provider authorization.',btn('Import wearable CSV','wearable-import','upload','button-primary'))}
 <div class="grid g4">${statCard('Wearable records',rows.length,'Imported CSV records','activity')}${statCard('Latest steps',rows[0]?.steps!=null?num(rows[0].steps):'—','No direct device connection','target')}${statCard('Sleep hours',rows[0]?.sleep_hours!=null?num(rows[0].sleep_hours,1):'—','Self-exported CSV','clock')}${statCard('Resting HR',rows[0]?.resting_hr!=null?num(rows[0].resting_hr):'—','bpm · if supplied','heart')}</div><div class="sp-18"></div><div class="split-2"><div class="panel">${panelHead('Import exported fitness data','Works with a simple CSV interchange format')}${btn('Choose CSV file','wearable-import','upload','button-primary')}<input id="csvImport" type="file" accept=".csv,text/csv" style="display:none"/><div class="sp-18"></div><p class="caption">Required header: <code>date</code>. Optional: <code>steps</code>, <code>sleep_hours</code>, <code>resting_hr</code>, <code>weight</code> (${esc(state.settings.unit)}).</p><pre class="example-csv">date,steps,sleep_hours,resting_hr,weight\n2026-11-21,8300,7.5,59,78.3</pre>${btn('Download CSV template','download-csv-template','download','button-tiny')}<div class="data-warning">Apple Health exports XML inside a ZIP; the PWA cannot natively read HealthKit or the watch sensors. Convert/export compatible records to this CSV format, or add an authorized native integration later.</div></div><div class="panel">${panelHead('Available sync modes','Keep private fitness records under your control')}<div class="list-row"><div class="list-icon">${icon('check-circle')}</div><div class="list-main"><strong>Offline-first browser tracking</strong><small>Always enabled on this device</small></div><span class="pill">Active</span></div><div class="list-row"><div class="list-icon">${icon('upload')}</div><div class="list-main"><strong>Backup / restore (JSON)</strong><small>Manual portable export</small></div><span class="pill">Ready</span></div><div class="list-row"><div class="list-icon">${icon('repeat')}</div><div class="list-main"><strong>Supabase cloud account</strong><small>Optional: add separate project keys in config.js</small></div><span class="pill">Optional</span></div><div class="sp-18"></div><div id="fitCloudRoot" class="cloud-panel">Cloud module loads here.</div></div></div><div class="sp-18"></div><div class="panel">${panelHead('Recent wearable imports','CSV data is stored locally')}${rows.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Steps</th><th>Sleep</th><th>Resting HR</th><th>Weight</th><th></th></tr></thead><tbody>${rows.slice(0,40).map(x=>`<tr><td>${fmtDate(x.date)}</td><td>${x.steps==null?'—':num(x.steps)}</td><td>${x.sleep_hours==null?'—':num(x.sleep_hours,1)+' h'}</td><td>${x.resting_hr==null?'—':num(x.resting_hr)}</td><td>${x.weight==null?'—':num(x.weight,1)}</td><td>${btn('Remove','wearable-delete','trash','button-tiny',`data-id="${esc(x.id)}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('activity','No data imported','Import your own CSV to compare activity and recovery context.')}</div>`;}

// Quick-start plan generator: always user-editable and non-medical.
function adaptivePlanForm(){modal('Build a training program',`${choiceField('days','Training days each week',[2,3,4,5,6].map(n=>({value:String(n),label:`${n} days`})),'4')}${choiceField('equipment','Available equipment',['Full gym','Dumbbells + Bodyweight','Bodyweight only'],state.settings.preferredEquipment||'Full gym')}${choiceField('goal','Primary goal',['Build muscle','Improve strength','Fat loss','General fitness','Endurance'],state.settings.goal||'Build muscle')}<p class="caption">Creates an editable starting template based on your schedule and available equipment. This is not an individualized medical or rehabilitation program. Existing plans are preserved.</p>`,v=>{const days=clamp(nval(v.days),2,6),equipment=v.equipment,goal=v.goal;let patterns=days===2?['Full Body A','Full Body B']:days===3?['Push','Pull','Legs']:days===4?['Upper A','Lower A','Upper B','Lower B']:['Push','Pull','Legs','Upper','Lower','Full Body'].slice(0,days);const desired={Push:['Chest','Shoulders','Arms'],Pull:['Back','Arms'],Legs:['Legs','Core'],Upper:['Chest','Back','Shoulders','Arms'],Lower:['Legs','Core'],'Full Body':['Chest','Back','Legs','Core']};const maxPer=5,planId=id();const specs=patterns.map((name,i)=>{let key=name.replace(/ [AB]$/,'').trim(),wanted=desired[key]||['Chest','Back','Legs'];let suitable=state.exercises.filter(e=>!e.custom&&(equipment==='Full gym'||(equipment==='Dumbbells + Bodyweight'?['Dumbbell','Bodyweight'].includes(e.equipment):e.equipment==='Bodyweight')));let chosen=[];for(const muscle of wanted){const candidates=suitable.filter(e=>e.muscle===muscle);if(candidates.length)chosen.push(candidates[(i+chosen.length)%candidates.length]);}for(const e of suitable)if(chosen.length<Math.min(maxPer,suitable.length)&&!chosen.includes(e))chosen.push(e);const reps=goal==='Improve strength'?6:goal==='Endurance'?15:goal==='Fat loss'?12:10;return {id:id(),title:name+' Day',weekday:[1,3,5,2,4,6][i],items:chosen.slice(0,maxPer).map(e=>({id:id(),exerciseId:e.id,sets:goal==='Improve strength'?3:3,reps,rest:goal==='Improve strength'?120:75}))}});
set(()=>{state.plans.push({id:planId,name:`${goal} · ${days}-Day ${equipment}`,description:'Adaptive starter · fully editable',days:specs});state.activePlanId=planId;state.settings.preferredEquipment=equipment;state.settings.goal=goal;ui.selectedPlanId=planId},'Adaptable training plan created');setPage('plans')},{saveLabel:'Create & activate plan'});}

